public function parse(Cell $cell): string
{
    $bracketPosition = strpos($this->value, self::OPEN_BRACE);
    if ($bracketPosition === false) {
        // A structured reference without any square brackets refers to the entire table
        $this->tableName = $this->value;
        $this->reference = '';
    } else {
        $this->tableName = substr($this->value, 0, $bracketPosition);
        $this->reference = substr($this->value, $bracketPosition);
    }

    $table = null;
    $cellsCollection = $cell->getParent();
    if ($cellsCollection !== null) {
        $cellWorksheet = $cellsCollection->getParent();
        if ($cellWorksheet !== null) {
            if ($this->tableName === '') {
                foreach ($cellWorksheet->getTableCollection() as $candidateTable) {
                    /** @var Table $candidateTable */
                    $candidateRange = $candidateTable->getRange();
                    if ($cell->isInRange($candidateRange) === true) {
                        if ($table === null) {
                            $this->tableName = $candidateTable->getName();
                            $table = $candidateTable;
                        }
                    }
                }
                if ($table === null) {
                    throw new Exception('Table for Structured Reference cannot be identified');
                }
            } else {
                $nameToFind = mb_convert_case($this->tableName, MB_CASE_UPPER, 'UTF-8');
                $spreadsheet = $cellWorksheet->getParent();
                if ($spreadsheet !== null) {
                    foreach ($spreadsheet->getAllSheets() as $candidateWorksheet) {
                        foreach ($candidateWorksheet->getTableCollection() as $candidateTable) {
                            /** @var Table $candidateTable */
                            $candidateName = mb_convert_case($candidateTable->getName(), MB_CASE_UPPER, 'UTF-8');
                            if ($candidateName === $nameToFind) {
                                if ($table === null) {
                                    $table = $candidateTable;
                                }
                            }
                        }
                    }
                }
                if ($table === null) {
                    throw new Exception("Table {$this->tableName} for Structured Reference cannot be located");
                }
            }

            $this->table = $table;
            $tableWorksheet = $table->getWorksheet() ?? $cellWorksheet;
            $tableRange = Coordinate::getRangeBoundaries($table->getRange());
            $this->headersRow = ($table->getShowHeaderRow()) ? (int) $tableRange[0][1] : null;
            $this->firstDataRow = ($table->getShowHeaderRow()) ? (int) $tableRange[0][1] + 1 : $tableRange[0][1];
            $this->totalsRow = ($table->getShowTotalsRow()) ? (int) $tableRange[1][1] : null;
            $this->lastDataRow = ($table->getShowTotalsRow()) ? (int) $tableRange[1][1] - 1 : $tableRange[1][1];

            $selectedCoordinate = $cell->getCoordinate();
            $columns = [];
